[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$Run,[Parameter(Mandatory=$true)][string]$Model,[ValidateSet('low','medium','high','xhigh')][string]$Effort='medium',[switch]$Execute,[string]$Root)
$ErrorActionPreference='Stop';if(-not $Root){$Root=Split-Path -Parent (Split-Path -Parent (Split-Path -Parent $PSScriptRoot))};$rootPath=(Resolve-Path $Root).Path
function To-WslPath([string]$Path){$full=[IO.Path]::GetFullPath($Path);if($full -notmatch '^([A-Za-z]):\\(.*)$'){throw "Unsupported Windows path: $full"};return "/mnt/$($Matches[1].ToLowerInvariant())/$($Matches[2].Replace('\','/'))"}
$runPath=if([IO.Path]::IsPathRooted($Run)){(Resolve-Path $Run).Path}else{(Resolve-Path (Join-Path $rootPath "Evals/runs/$Run")).Path};$manifest=Get-Content -Raw (Join-Path $runPath 'run-manifest.json')|ConvertFrom-Json;$workspace=Join-Path $runPath $manifest.workspace;$agentic=Join-Path $workspace '.agentic';New-Item -ItemType Directory -Force -Path $agentic|Out-Null
Copy-Item -LiteralPath (Join-Path $runPath 'prompt.txt') -Destination (Join-Path $agentic 'BENCHMARK_PROMPT.txt') -Force;Copy-Item -LiteralPath (Join-Path $rootPath 'Evals/isolation/codex-run-inner.sh') -Destination (Join-Path $agentic 'codex-run-inner.sh') -Force
$repoWsl=To-WslPath $rootPath;$workspaceWsl=To-WslPath $workspace;$sandbox="$repoWsl/Evals/isolation/wsl-sandbox.sh";$wslHome=(wsl -d Ubuntu -- printenv HOME|Out-String).Trim();$codexWsl="$wslHome/.local/bin/codex";$wslPath="$wslHome/.local/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin";$version=(wsl -d Ubuntu -- env "PATH=$wslPath" $codexWsl --version 2>&1|Out-String).Trim();$previousErrorPreference=$ErrorActionPreference;$ErrorActionPreference='Continue';$login=(wsl -d Ubuntu -- env "PATH=$wslPath" $codexWsl login status 2>&1|Out-String).Trim();$loginExit=$LASTEXITCODE;$ErrorActionPreference=$previousErrorPreference;$ready=$loginExit -eq 0 -and $version -match 'codex-cli' -and $login -match 'Logged in'
$preview=[ordered]@{schema_version=1;provider='codex-wsl';version=$version;login_status=$login;ready=$ready;workspace=$workspace;model=$Model;effort=$Effort;isolation='wsl-user-mount-namespace';execute=[bool]$Execute}
if(-not $Execute){$preview|ConvertTo-Json -Depth 6;exit 3};if(-not $ready){throw "Codex WSL is not ready: $login"}
$started=[datetimeoffset]::Now;$old=$ErrorActionPreference;$ErrorActionPreference='Continue';$output=wsl -d Ubuntu -- env AGENTIC_COPY_CODEX_AUTH=1 AGENTIC_MODEL=$Model AGENTIC_EFFORT=$Effort bash $sandbox $workspaceWsl bash .agentic/codex-run-inner.sh 2>&1|Out-String;$exit=$LASTEXITCODE;$ErrorActionPreference=$old;$record=[ordered]@{schema_version=1;provider='codex-wsl';provider_version=$version;model_requested=$Model;effort=$Effort;started_at=$started.ToString('o');finished_at=[datetimeoffset]::Now.ToString('o');exit_code=$exit;output=$output;events_path='.agentic/provider-events.jsonl';isolation='wsl-user-mount-namespace'};$record|ConvertTo-Json -Depth 8|Set-Content -Encoding UTF8 (Join-Path $runPath 'provider-execution.json');$record|ConvertTo-Json -Depth 8;exit $exit
